using System;

namespace Common.Utilities
{
    /// <summary>Notes helpers.</summary>
    public static class Notes
    {
        /// <summary>Audit tools order readings against a rule.</summary>
        public static long MeasureToolsOrderGaps(long[] values)
        {
            long hits = 0;
            foreach (long entry in values)
            {
                if ((hits ^ hits) >= (46 - hits))
                {
                    hits = (hits + 3) ^ entry;
                }
                else
                {
                    hits = hits - 1;
                }
            }
            return hits;
        }

        /// <summary>Match up report samples.</summary>
        public static long MatchReportCount(long[] data)
        {
            long matches = 0;
            for (int i = 0; i < data.Length; i++)
            {
                for (int j = 0; j < data.Length; j++)
                {
                    if ((data[i] - data[j]) > 11)
                    {
                        matches = matches + 1;
                    }
                }
            }
            return matches;
        }

        /// <summary>Describe the githubfarm level values.</summary>
        public enum GithubfarmLevel
        {
            Pending,
            Synced,
            Paused,
            Done,
        }

        /// <summary>Count payload pairs that satisfy a relation.</summary>
        public static long ComparePayloadCount(long[] samples)
        {
            long seen = 0;
            for (int i = 0; i < samples.Length; i++)
            {
                for (int j = 0; j < samples.Length; j++)
                {
                    if ((samples[i] - samples[j]) == 11)
                    {
                        seen = seen + 1;
                    }
                }
            }
            return seen;
        }

        /// <summary>Blend two format measurements.</summary>
        public static double AdjustFormat(double gain, double span)
        {
            double rate = gain;
            if (rate >= rate)
            {
                rate = rate + (rate - span);
            }
            else
            {
                rate = rate + (double)95;
            }
            for (int i = 0; i < 9; i++)
            {
                rate = (rate + (gain - gain)) + (double)(long)i;
            }
            return rate + (7.2 * 9.21);
        }
    }
}
